import React, { forwardRef } from 'react';

import { CategoricalBarChart } from './CategoricalBarChart.js';
import { CategoricalBarChartLegend } from './components/legend/CategoricalBarChartLegend.js';
import { isStacked, isGrouped } from './functions/layout.js';
import { useCategoricalBarChartBaseConfig } from './hooks/useCategoricalBarChartBaseConfig.js';
import { useCategoricalBarChartData } from './hooks/useCategoricalBarChartData.js';
import { CategoricalBarChartLegendConfiguration } from './types/categorical-bar-chart.js';
import type { StylingProps } from '../../core/types/styling-props.js';
import { ChartLayout } from '../core/components/chart-layout/ChartLayout.js';
import { CATEGORICAL_LEGEND_SIZES } from '../core/components/legend/categorical/constants.js';
import { defaultRatio } from '../core/constants.js';

interface CategoricalBarChartLayoutProps extends StylingProps {
  emptyState?: React.ReactNode;
  errorState:
    | React.ReactNode
    | ((errorMessage: string) => JSX.Element)
    | undefined;
  legend: CategoricalBarChartLegendConfiguration;
  isEmpty: boolean;
  loading: boolean;
  height?: string;
  width?: number;
}

export const CategoricalBarChartLayout = /* @__PURE__ */ forwardRef<
  HTMLDivElement,
  CategoricalBarChartLayoutProps
>((props, forwardedRef) => {
  const {
    height,
    width,
    legend,
    isEmpty,
    loading,
    errorState,
    emptyState,
    className,
    style,
  } = props;
  const { uniqueDimensions } = useCategoricalBarChartData();
  const { groupMode } = useCategoricalBarChartBaseConfig();

  const canShowLegend =
    isGrouped(groupMode) ||
    (isStacked(groupMode) && uniqueDimensions.length > 1);
  const { ratio = defaultRatio } = legend;

  const showLegend = canShowLegend && !legend.hidden;

  const legendConfig = {
    ratio,
    hidden: !showLegend,
    orientation: !showLegend ? undefined : legend.position,
    sizes: CATEGORICAL_LEGEND_SIZES,
  };

  return (
    <ChartLayout
      chartHeight={height}
      chartWidth={width}
      resizable={legend.resizable}
      isEmpty={isEmpty}
      emptyState={emptyState}
      errorState={errorState}
      showLoader={loading}
      legendConfig={legendConfig}
      className={className}
      style={style}
    >
      <ChartLayout.Graph>
        <CategoricalBarChart ref={forwardedRef} />
      </ChartLayout.Graph>
      {showLegend && (
        <ChartLayout.Legend>
          <CategoricalBarChartLegend />
        </ChartLayout.Legend>
      )}
    </ChartLayout>
  );
});

CategoricalBarChartLayout['displayName'] = 'CategoricalBarChartLayout';
